question.answer:
package main

type Duck struct{}

type Toy struct{}

type Quacker interface {
	Quack() string
}

func (d Duck) Quack() string {
	return "quack"
}

func (t Toy) Quack() string {
	return "squeak"
}

func chorus(pond []Quacker) []string {
	var out []string
	for _, q := range pond {
		if q == nil {
			continue
		}
		out = append(out, q.Quack())
	}
	return out
}

