question.answer:
package main

import "fmt"

type Thermometer struct {
	Celsius float64
}

func (t Thermometer) Sample() float64 { return t.Celsius }

func (t Thermometer) Name() string { return "thermometer" }

func (t Thermometer) Calibrated(offset float64) Thermometer {
	return Thermometer{Celsius: t.Celsius + offset}
}

type Barometer struct {
	Millibars float64
}

func (b Barometer) Sample() float64 { return b.Millibars }

func (b Barometer) Name() string { return "barometer" }

type Dial struct {
	Value float64
}

func (d Dial) Sample() float64 { return d.Value }

type Nameplate struct {
	Label string
}

func (n Nameplate) Name() string { return n.Label }

type Sampler interface {
	Sample() float64
}

type Namer interface {
	Name() string
}

type Instrument interface {
	Sampler
	Namer
}

func mean(ss []Sampler) float64 {
	total := 0.0
	n := 0.0
	for _, s := range ss {
		total += s.Sample()
		n++
	}
	if n == 0 {
		return 0
	}
	return total / n
}

func entry(in Instrument) string {
	return fmt.Sprintf("%s: %v", in.Name(), in.Sample())
}

testcode.text:
var s Sampler = Dial{Value: 3.5}
_, isNamer := s.(Namer)
fmt.Println(s.Sample(), isNamer, mean([]Sampler{s, Dial{}, Thermometer{Celsius: 21}}))

var in Instrument = Barometer{Millibars: 998}
var n Namer = in
var s Sampler = in
var plate Namer = Nameplate{Label: "porch"}
fmt.Println(entry(in), n.Name(), s.Sample(), mean(nil), plate.Name())

