question.answer:
package main

import "fmt"

type Seat int

const (
	FirstViolin Seat = iota
	SecondViolin
	Viola
	Cello
)

type Player struct {
	Name string
	Seat Seat
}

func (s Seat) String() string {
	switch s {
	case FirstViolin:
		return "first violin"
	case SecondViolin:
		return "second violin"
	case Viola:
		return "viola"
	case Cello:
		return "cello"
	}
	return fmt.Sprintf("seat %d", s)
}

func (p Player) String() string {
	return fmt.Sprintf("%s (%v)", p.Name, p.Seat)
}

testcode.text:
p := Player{Name: "Ana", Seat: Viola}
fmt.Println(p)
fmt.Printf("%s\n", p)

quartet := []Player{{"Cy", FirstViolin}, {"Di", SecondViolin}, {"Ana", Viola}, {"Bo", Cello}}
fmt.Println(quartet)
type desk struct {
	Seat  Seat
	spare Seat
}
fmt.Println(desk{Viola, Cello})

