package main

import "slices"

// The AI wrote this. It passes every test. Judge it, then rewrite it.

// Store is everything a store can do.
type Store interface {
	Get(key string) string
	Put(key, value string)
	Delete(key string)
	Keys() []string
	Len() int
}

// StoreImpl implements Store with a map.
type StoreImpl struct {
	data map[string]string
}

// NewStore returns an empty Store.
func NewStore() Store {
	return &StoreImpl{data: map[string]string{}}
}

func (s *StoreImpl) Get(key string) string { return s.data[key] }

func (s *StoreImpl) Put(key, value string) { s.data[key] = value }

func (s *StoreImpl) Delete(key string) { delete(s.data, key) }

func (s *StoreImpl) Keys() []string {
	var keys []string
	for k := range s.data {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	return keys
}

func (s *StoreImpl) Len() int { return len(s.data) }

// render returns one line per key, as key=value.
func render(s Store, keys []string) []string {
	var lines []string
	for _, k := range keys {
		lines = append(lines, k+"="+s.Get(k))
	}
	return lines
}

question.answer:
package main

import "slices"

// MemStore keeps props in a map.
type MemStore struct {
	data map[string]string
}

// NewStore returns an empty MemStore.
func NewStore() *MemStore {
	return &MemStore{data: map[string]string{}}
}

func (s *MemStore) Get(key string) string { return s.data[key] }

func (s *MemStore) Put(key, value string) { s.data[key] = value }

func (s *MemStore) Delete(key string) { delete(s.data, key) }

func (s *MemStore) Keys() []string {
	var keys []string
	for k := range s.data {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	return keys
}

func (s *MemStore) Len() int { return len(s.data) }

// Getter is what render needs from a store.
type Getter interface {
	Get(key string) string
}

// render returns one line per key, as key=value.
func render(s Getter, keys []string) []string {
	var lines []string
	for _, k := range keys {
		lines = append(lines, k+"="+s.Get(k))
	}
	return lines
}
